#include <windows.h>
#include <stdio.h>
#include <stdint.h>
#include <string.h>
static int writes;
static void __cdecl capture(const void *data,int length,int handle) {
  printf("write handle=%d length=%d text=[%.*s]\n",handle,length,length,(const char*)data);
  ++writes;
}
int main(void) {
  HMODULE module=LoadLibraryA("qagamex86.dll");
  void *imports[207]={0}, *exports=0;
  int api=0;
  void (__cdecl *entry)(void**,void**,int*);
  void (__cdecl *logMessage)(const char*,...);
  if(!module){printf("load error %lu\n",GetLastError());return 1;}
  entry=(void (__cdecl *)(void**,void**,int*))GetProcAddress(module,"dllEntry");
  if(!entry)return 2;
  imports[4]=(void*)capture;
  entry(&exports,imports,&api);
  if(api!=10)return 3;
  /* Observed data addresses for this hash-pinned module only; no code patching. */
  *(int*)((unsigned char*)module+0x5dce54)=1; /* log handle */
  *(int*)((unsigned char*)module+0x5dce5c)=123000; /* level time */
  logMessage=(void (__cdecl *)(const char*,...))((unsigned char*)module+0x573f0);
  logMessage("FNTECH3_LOG_FIXTURE_LITERAL\n");
  logMessage("FNTECH3_LOG_FIXTURE_VALUE=%d\n",42);
  FreeLibrary(module);
  return writes==2 ? 0 : 4;
}
